mapper.select:
SELECT s.apply_yyyymm, s.income_type, s.code, s.headcount, s.tax_total,
/* 징수농특세: 스키마 분리항목 없음 → 일단 tax_nt를 동치로 노출 */ s.tax_nt AS nt_withheld,
/* 납부소득세 = 징수소득세 - 조정환급세액 */ (NVL(s.tax_income,0) - NVL(s.adj_refund,0)) AS tax_income,
/* 징수가산세: 스키마에 없으므로 0 */ 0 AS penalty_tax,
/* 징수소득세 = 스키마의 tax_income */ s.tax_income AS tax_withheld,
/* 조정환급세액/납부농특세 원본 */ s.adj_refund, s.tax_nt,
ROW_NUMBER() OVER (ORDER BY s.code) AS no FROM wh_withholding_summary s WHERE s.apply_yyyymm = #{applyYyyymm} ORDER BY s.code

SELECT
  a.apply_yyyymm,
  a.income_type,
  a.code,

  /* 부표는 인원/총지급액 없음 → 0 */
  0 AS headcount,
  0 AS tax_total,

  /* 징수농특세: 일단 0 고정 (룰 결정되면 CASE WHEN으로 매핑) */
  0 AS nt_withheld,

  /* 납부소득세: 부표 단독으론 환급정보가 없으므로 = 징수소득세 */
  CASE WHEN a.code LIKE 'T_IN-%' THEN NVL(a.amount,0) ELSE 0 END AS tax_income,

  /* 징수가산세 없음 → 0 */
  0 AS penalty_tax,

  /* 징수소득세: T_IN-* 코드 금액 */
  CASE WHEN a.code LIKE 'T_IN-%' THEN NVL(a.amount,0) ELSE 0 END AS tax_withheld,

  /* 조정환급세액: 부표에는 없음 → 0 */
  0 AS adj_refund,

  /* 납부농특세: T_NT-* 코드 금액 */
  CASE WHEN a.code LIKE 'T_NT-%' THEN NVL(a.amount,0) ELSE 0 END AS tax_nt,

  ROW_NUMBER() OVER (ORDER BY a.code) AS no
FROM wh_annex a
WHERE a.apply_yyyymm = #{applyYyyymm}
ORDER BY a.code
